import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { findConfigFile } from "../load-config.ts";
import { writeIfChanged } from "./write-if-changed.ts";

/** Generated files live here (gitignored). React Router's `appDirectory` points at `.consify/app`. */
export const generatedDir = ".consify";
export const appDirectory = `${generatedDir}/app`;

export const header = "// Generated by consify. Do not edit, do not commit.";

/** Source of `.consify/instance.ts`: the site at runtime, built from the config of the project. */
export function renderInstance(configFile = "docs.config.ts"): string {
  return `${header}
// @ts-nocheck: the type of \`consify\` seen by route modules is declared by "consify:instance" instead.
import { componentsFromGlob, createConsify, localesFromGlob, slotsFromGlob } from "@consify/core/runtime";
import config from "../${configFile}";

export const consify = createConsify(config, {
  // custom/components/Foo.tsx is <Foo /> in every .mdx file
  components: componentsFromGlob(import.meta.glob("/custom/components/*.{tsx,jsx}", { eager: true })),
  // custom/header.tsx and custom/footer.tsx replace those parts of the site
  slots: slotsFromGlob(import.meta.glob("/custom/{header,footer}.{tsx,jsx}", { eager: true })),
  // custom/locales/<language>.ts (or .json): the strings of the interface in that language
  locales: localesFromGlob(import.meta.glob("/custom/locales/*.{ts,json}", { eager: true })),
});
`;
}

/**
 * Source of `.consify/content.ts`: the text files of `content/`, compiled into the server build so a
 * built server does not need the folder next to it.
 */
export function renderContent(): string {
  return `${header}
export const content = import.meta.glob("/content/**/*.{md,mdx,json,yml,yaml,txt}", {
  query: "?raw",
  import: "default",
});
`;
}

export function renderRoot(hasCustomCss: boolean): string {
  return `${header}
import "../styles.css";
${hasCustomCss ? 'import "../../custom/theme.css";\n' : ""}export { default, ErrorBoundary, Layout } from "@consify/core/react-router/root";
`;
}

export function renderRoutes(configFile = "docs.config.ts"): string {
  return `${header}
import { routes } from "@consify/core/react-router/routes";
import config from "../../${configFile}";

export default await routes(config);
`;
}

/**
 * The folders of the consify packages the project depends on (`@consify/blog`, …). Tailwind only
 * makes the classes it finds in the files it scans, and their pages live outside the project.
 */
export function packageDirs(cwd: string): string[] {
  let manifest: { dependencies?: object; devDependencies?: object } = {};
  try {
    manifest = JSON.parse(readFileSync(join(cwd, "package.json"), "utf8"));
  } catch {
    return [];
  }
  const require = createRequire(join(cwd, "package.json"));
  const names = Object.keys({ ...manifest.dependencies, ...manifest.devDependencies }).filter(
    (name) => name.startsWith("@consify/") || name.startsWith("consify-"),
  );
  return names.flatMap((name) => {
    try {
      return [realpathSync(dirname(require.resolve(`${name}/package.json`)))];
    } catch {
      return [];
    }
  });
}

/** Source of `.consify/styles.css`: the theme of consify, plus the packages Tailwind has to scan. */
export function renderStyles(dirs: readonly string[]): string {
  const sources = dirs.map((dir) => `@source ${JSON.stringify(dir)};`);
  return `/* Generated by consify. Do not edit, do not commit. */\n@import "@consify/core/theme.css";\n${sources.join("\n")}${sources.length > 0 ? "\n" : ""}`;
}

/**
 * Writes the thin files React Router needs into `.consify/`, so a project keeps only
 * `docs.config.ts`, `vite.config.ts` and `react-router.config.ts`. Safe to call repeatedly.
 */
export function scaffold(cwd: string = process.cwd()): void {
  // what an older version generated is not left behind to be compiled
  const own = new Set(["app", "routes", "instance.ts", "content.ts", "styles.css"]);
  const dir = join(cwd, generatedDir);
  if (existsSync(dir)) {
    for (const name of readdirSync(dir)) {
      if (!own.has(name)) rmSync(join(dir, name), { recursive: true, force: true });
    }
  }
  const configFile = findConfigFile(cwd) ?? "docs.config.ts";
  writeIfChanged(join(cwd, generatedDir, "instance.ts"), renderInstance(configFile));
  writeIfChanged(join(cwd, generatedDir, "content.ts"), renderContent());
  writeIfChanged(join(cwd, generatedDir, "styles.css"), renderStyles(packageDirs(cwd)));
  writeIfChanged(
    join(cwd, appDirectory, "root.tsx"),
    renderRoot(existsSync(join(cwd, "custom/theme.css"))),
  );
  writeIfChanged(join(cwd, appDirectory, "routes.ts"), renderRoutes(configFile));
}
